code='''def transform(grid):
    out = [row[:] for row in grid]
    h = len(out)
    w = len(out[0]) if h else 0
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if out[r][c] == out[r][c + 1] == out[r + 1][c] == out[r + 1][c + 1] == 0:
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        return out
    _, c = marker
    for row in out:
        for j in (c, c + 1):
            if row[j] != 2:
                row[j] = 0
    return out
'''
