def check_cols(rows, c):
    # Non-target cells are harmless sentinels; the task changes only marker columns.
    g=[[1]*20 for _ in range(20)]
    for r,vals in enumerate(rows):
        g[r][c:c+2]=vals
    got=transform(g)
    expected=[[0 if v != 2 else 2 for v in vals] for vals in rows]
    for rr in (next(i for i in range(19) if rows[i]==[0,0] and rows[i+1]==[0,0]),):
        expected[rr]=[0,0]; expected[rr+1]=[0,0]
    return [got[r][c:c+2] for r in range(20)] == expected
